                      <Mail className="h-3.5 w-3.5 text-indigo-600" />
                    </div>
                    <div>
                      <p className="text-xs text-slate-400">Suggested by</p>
                      <p className="text-sm font-medium text-slate-700 truncate">{detail.suggesterEmail}</p>
                    </div>
                  </div>
                )}
